    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.45+3)*70,120+Math.cos(t*0.65+4)*60,0.11,2.1],
    [400+Math.cos(t*0.55+2)*60,140+Math.sin(t*0.75+1)*50,0.085,1.8],
    [200+Math.sin(t*0.38+6)*110,40+Math.cos(t*0.48+3)*70,0.095,2.4]
