  let aS=0,iS=0,hS=0;
  for(const[sX,sY,f,sp]of src){const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);aS+=Math.sin(d*f-t*sp);iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);hS+=Math.sin(d*f*1.3-t*sp*0.4+3.0);}
